  @Test
  void blockWaitsForRoom() throws Exception {
    CountDownLatch busy = new CountDownLatch(1);
    AtomicBoolean slowCallback = new AtomicBoolean(true);
    exporter.enqueueOutcome(b -> CompletableFuture.failedFuture(new ValidationException("bad")));
    BatchProcessor p =
        new BatchProcessor(
            exporter,
            opts()
                .maxQueueSize(1)
                .maxBatchSize(1)
                .dropPolicy(DropPolicy.BLOCK)
                .onError(
                    (e, r) -> {
                      if (slowCallback.getAndSet(false)) {
                        busy.countDown();
                        sleep(400); // keeps the worker busy
                      }
                    })
                .build());
    p.add(rec("a")); // export fails, the error callback blocks the worker
    await(busy);
    p.add(rec("b")); // fills the queue
    long start = System.nanoTime();
    assertThat(p.add(rec("c"))).isTrue(); // waits until the worker frees room
    assertThat(System.nanoTime() - start).isGreaterThan(TimeUnit.MILLISECONDS.toNanos(150));
    p.shutdown();
    assertThat(exporter.records()).extracting(LogRecord::body).containsExactly("b", "c");
    assertThat(drops).containsExactly("export_failed:1");
  }

