  @Test
  void shutdownIsIdempotentAndDropsLaterRecords() throws Exception {
    BatchProcessor p = new BatchProcessor(exporter, opts().build());
    p.add(rec("a"));
    CompletableFuture<Void> first = p.shutdownAsync(Duration.ofSeconds(5));
    assertThat(p.shutdownAsync(Duration.ofSeconds(5))).isSameAs(first);
    first.get(5, TimeUnit.SECONDS);
    p.close();
    assertThat(p.add(rec("late"))).isFalse();
    assertThat(drops).containsExactly("shutdown:1");
    assertThat(exporter.records()).hasSize(1);
    assertThat(exporter.shutdownCount()).isEqualTo(1);
    p.flush(); // no-op after shutdown
    assertThat(p.stats().dropped()).isEqualTo(1);
  }

  @Test
  void shutdownTimeoutDropsRemainingRecords() throws Exception {
    CountDownLatch started = new CountDownLatch(1);
    exporter.enqueueOutcome(hanging(started));
    BatchProcessor p = new BatchProcessor(exporter, opts().maxBatchSize(1).build());
    p.add(rec("a"));
    await(started);
    p.add(rec("b"));
    p.add(rec("c"));
    // The worker is parked on the hanging export of "a", so "b" and "c" stay queued until the
    // shutdown deadline; the timeout then drops both atomically and interrupts the export of "a".
    assertThatThrownBy(() -> p.shutdown(Duration.ofMillis(100)))
        .isInstanceOf(TimeoutException.class);
    assertThat(drops).contains("shutdown:2");
    eventually(() -> drops.size() == 2 && p.stats().queued() == 0);
    assertThat(drops).containsExactlyInAnyOrder("shutdown:2", "export_failed:1");
    assertThat(exporter.batchSizes()).containsExactly(1);
  }

